__device__ __forceinline__ int wrap_y_coordinate(int q)
{
  if (q < 0) {
    q += 63;
  } else if (q > 63) {
    q -= 63;
  }
  return q;
}

__device__ __forceinline__ float load_y_sample(const float *f, int i, int k, int q)
{
  const int y = wrap_y_coordinate(q);
  return f[k * mx * my + y * mx + i];
}

// Each warp spans adjacent X coordinates. Each thread rolls a nine-value
// Y window through up to six consecutive outputs, without shared memory.
__global__ void derivative_y_rolling(const float *f, float *df)
{
  const int i = blockIdx.x * blockDim.x + threadIdx.x;
  const int y_group = blockIdx.y * yGroupsPerBlock + threadIdx.y;
  const int k = blockIdx.z;
  const int first_y = y_group * yOutputsPerThread;

  if (i >= mx || k >= mz || first_y >= my) {
    return;
  }

  float v0 = load_y_sample(f, i, k, first_y - 4);
  float v1 = load_y_sample(f, i, k, first_y - 3);
  float v2 = load_y_sample(f, i, k, first_y - 2);
  float v3 = load_y_sample(f, i, k, first_y - 1);
  float v4 = load_y_sample(f, i, k, first_y);
  float v5 = load_y_sample(f, i, k, first_y + 1);
  float v6 = load_y_sample(f, i, k, first_y + 2);
  float v7 = load_y_sample(f, i, k, first_y + 3);
  float v8 = load_y_sample(f, i, k, first_y + 4);

#pragma unroll
  for (int r = 0; r < yOutputsPerThread; ++r) {
    const int j = first_y + r;
    if (j < my) {
      const int output_index = k * mx * my + j * mx + i;
      df[output_index] =
        ( c_ay * (v5 - v3)
        + c_by * (v6 - v2)
        + c_cy * (v7 - v1)
        + c_dy * (v8 - v0) );
    }

    if (r + 1 < yOutputsPerThread && j + 1 < my) {
      v0 = v1;
      v1 = v2;
      v2 = v3;
      v3 = v4;
      v4 = v5;
      v5 = v6;
      v6 = v7;
      v7 = v8;
      v8 = load_y_sample(f, i, k, j + 5);
    }
  }
}

