__global__ void derivative_y(float *f, float *df)
{
  __shared__ float s_f[Y_TILE + 8][lPencils];

  int tx = threadIdx.x;
  int ty = threadIdx.y;
  int i = blockIdx.x * blockDim.x + tx;
  int k = blockIdx.z;
  int yBase = blockIdx.y * Y_TILE;
  int planeOffset = k * mx * my;

  // Cooperatively initialize every tile row, including both four-row halos.
  // Only coordinates outside [0, 63] wrap, by the required period of 63.
#pragma unroll
  for (int load = 0; load < (Y_TILE + 8) / Y_THREADS; ++load) {
    int tileRow = ty + load * Y_THREADS;
    int q = yBase + tileRow - 4;
    if (q < 0) q += my - 1;
    else if (q > my - 1) q -= my - 1;
    s_f[tileRow][tx] = f[planeOffset + q * mx + i];
  }
  __syncthreads();

  // Each Y thread computes its eight output rows from the initialized tile.
#pragma unroll
  for (int output = 0; output < Y_TILE / Y_THREADS; ++output) {
    int localY = ty + output * Y_THREADS;
    int sj = localY + 4;
    int globalY = yBase + localY;
    int globalIdx = planeOffset + globalY * mx + i;

    df[globalIdx] =
      ( c_ay * ( s_f[sj+1][tx] - s_f[sj-1][tx] )
      + c_by * ( s_f[sj+2][tx] - s_f[sj-2][tx] )
      + c_cy * ( s_f[sj+3][tx] - s_f[sj-3][tx] )
      + c_dy * ( s_f[sj+4][tx] - s_f[sj-4][tx] ) );
  }
}

