__device__ __forceinline__ int wrap_y(int q)
{
  if (q < 0) {
    q += 63;
  } else if (q > 63) {
    q -= 63;
  }
  return q;
}

// Direct global loads: one output per thread, with each warp spanning X.
__global__ void derivative_y_direct(const float *f, float *df)
{
  int i = blockIdx.x * blockDim.x + threadIdx.x;
  int j = blockIdx.y * blockDim.y + threadIdx.y;
  int k = blockIdx.z * blockDim.z + threadIdx.z;

  if (i >= mx || j >= my || k >= mz) return;

  int base = k * mx * my + i;
  int jm1 = wrap_y(j - 1);
  int jm2 = wrap_y(j - 2);
  int jm3 = wrap_y(j - 3);
  int jm4 = wrap_y(j - 4);
  int jp1 = wrap_y(j + 1);
  int jp2 = wrap_y(j + 2);
  int jp3 = wrap_y(j + 3);
  int jp4 = wrap_y(j + 4);

  df[base + j * mx] =
    ( c_ay * ( f[base + jp1 * mx] - f[base + jm1 * mx] )
    + c_by * ( f[base + jp2 * mx] - f[base + jm2 * mx] )
    + c_cy * ( f[base + jp3 * mx] - f[base + jm3 * mx] )
    + c_dy * ( f[base + jp4 * mx] - f[base + jm4 * mx] ) );
}

extern "C" void run(const float *A, const float *B, float *C,
                    float *scratch, int n, int m, int k,
                    float alpha, float beta)
{
  static bool initialized = false;
  if (!initialized) {
    setDerivativeParameters();
    initialized = true;
  }

  // Keep 16 X-spanning warps per CTA, grouping two Z planes alongside 8 Y rows.
  dim3 directBlock(32, 8, 2);
  dim3 directGrid((mx + directBlock.x - 1) / directBlock.x,
                  (my + directBlock.y - 1) / directBlock.y,
                  (mz + directBlock.z - 1) / directBlock.z);
  derivative_y_direct<<<directGrid, directBlock>>>(A, C);
}

