__device__ __forceinline__ int wrapped_y(int q)
{
  if (q < 0) q += 63;
  else if (q > 63) q -= 63;
  return q;
}

// Each thread rolls a nine-value Y window across three consecutive outputs.
// The 32 X threads in each warp access adjacent elements in every input row.
__global__ void derivative_y(const float *f, float *df)
{
  const int i = blockIdx.x * blockDim.x + threadIdx.x;
  const int k = blockIdx.z;
  int j = blockIdx.y * blockDim.y * yOutputsPerThread
        + threadIdx.y * yOutputsPerThread;

  if (i >= mx || k >= mz || j >= my) return;

  const int offset = k * mx * my + i;
  float v0 = f[offset + wrapped_y(j - 4) * mx];
  float v1 = f[offset + wrapped_y(j - 3) * mx];
  float v2 = f[offset + wrapped_y(j - 2) * mx];
  float v3 = f[offset + wrapped_y(j - 1) * mx];
  float v4 = f[offset + wrapped_y(j) * mx];
  float v5 = f[offset + wrapped_y(j + 1) * mx];
  float v6 = f[offset + wrapped_y(j + 2) * mx];
  float v7 = f[offset + wrapped_y(j + 3) * mx];
  float v8 = f[offset + wrapped_y(j + 4) * mx];

  #pragma unroll
  for (int out = 0; out < yOutputsPerThread; ++out) {
    if (j >= my) break;

    df[offset + j * mx] =
      ( c_ay * (v5 - v3)
      + c_by * (v6 - v2)
      + c_cy * (v7 - v1)
      + c_dy * (v8 - v0) );

    ++j;
    if (out + 1 < yOutputsPerThread && j < my) {
      v0 = v1;
      v1 = v2;
      v2 = v3;
      v3 = v4;
      v4 = v5;
      v5 = v6;
      v6 = v7;
      v7 = v8;
      v8 = f[offset + wrapped_y(j + 4) * mx];
    }
  }
}

extern "C" void run(const float *A, const float *B, float *C,
                    float *scratch, int n, int m, int k,
                    float alpha, float beta)
{
  static bool initialized = false;
  if (!initialized) {
    setDerivativeParameters();
    initialized = true;
  }

  const int yOutputsPerBlock = yThreadsPerBlock * yOutputsPerThread;
  dim3 launchGrid((mx + 31) / 32,
                  (my + yOutputsPerBlock - 1) / yOutputsPerBlock,
                  mz);
  dim3 launchBlock(32, yThreadsPerBlock, 1);
  derivative_y<<<launchGrid, launchBlock>>>(A, C);
}

