  block[2][1] = dim3(lPencils, mz * sPencils / lPencils, 1);
}

__device__ __forceinline__ int wrapY(int q)
{
  if (q < 0) {
    q += my - 1;
  } else if (q > my - 1) {
    q -= my - 1;
  }
  return q;
}

__device__ __forceinline__ float loadY(const float *f, int i, int k, int q)
{
  const int wrappedQ = wrapY(q);
  return f[k * mx * my + wrappedQ * mx + i];
}

__global__ void derivative_y(float *f, float *df)
{
  const int i = blockIdx.x * blockDim.x + threadIdx.x;
  const int firstY = blockIdx.y * outputChunk;
  const int k = blockIdx.z;
  if (i >= mx || firstY >= my || k >= mz) {
    return;
  }

  // Nine consecutive Y samples stay in registers as the output window advances.
  float r0 = loadY(f, i, k, firstY - 4);
  float r1 = loadY(f, i, k, firstY - 3);
  float r2 = loadY(f, i, k, firstY - 2);
  float r3 = loadY(f, i, k, firstY - 1);
  float r4 = loadY(f, i, k, firstY);
  float r5 = loadY(f, i, k, firstY + 1);
  float r6 = loadY(f, i, k, firstY + 2);
  float r7 = loadY(f, i, k, firstY + 3);
  float r8 = loadY(f, i, k, firstY + 4);

  #pragma unroll
  for (int t = 0; t < outputChunk; ++t) {
    const int j = firstY + t;
    if (j < my) {
      const int globalIdx = k * mx * my + j * mx + i;
      df[globalIdx] =
          c_ay * (r5 - r3)
        + c_by * (r6 - r2)
        + c_cy * (r7 - r1)
        + c_dy * (r8 - r0);
    }

    if (t + 1 < outputChunk) {
      r0 = r1;
      r1 = r2;
      r2 = r3;
      r3 = r4;
      r4 = r5;
      r5 = r6;
      r6 = r7;
      r7 = r8;
      r8 = loadY(f, i, k, firstY + t + 5);
    }
  }
}

extern "C" void run(const float *A, const float *B, float *C,
                    float *scratch, int n, int m, int k,
                    float alpha, float beta)
{
  static bool initialized = false;
  if (!initialized) {
    setDerivativeParameters();
    initialized = true;
  }

  const dim3 registerBlock(32, 1, 1);
  const dim3 registerGrid((mx + 31) / 32,
                          (my + outputChunk - 1) / outputChunk,
                          mz);
  derivative_y<<<registerGrid, registerBlock>>>((float *)A, C);
}

