// Map a neighbor coordinate using the supplied period-63 boundary rule.
// In-range coordinate 63 is intentionally not remapped.
__device__ __forceinline__ int wrap_y_coordinate(int q)
{
  if (q < 0) {
    q += 63;
  } else if (q > 63) {
    q -= 63;
  }
  return q;
}

__device__ __forceinline__ float load_y_sample(const float *f, int i, int k, int q)
{
  q = wrap_y_coordinate(q);
  return f[(k * my + q) * mx + i];
