    initialized = true;
  }

  const dim3 launch_block(32, 4, 1);
  const dim3 launch_grid((mx + 31) / 32, (my + 15) / 16, mz);
  derivative_y<<<launch_grid, launch_block>>>((const float *)A, C);
}

